// SPDX-License-Identifier: Apache-2.0
// Module: JIT Compilation Semantics
// phi^2 + 1/phi^2 = 3 | TRINITY

module JitSemantics {
    // ========================================================================
    // IMPORTS - Reference existing specs, DO NOT DUPLICATE
    // ========================================================================
    use base::types;          // Trit enum
    use ternary::hybrid_arithmetic; // HybridBigInt for operands
    use numeric::gf16;          // GF16 for numeric values

    // ========================================================================
    // 1. Function Pointer Types
    // ========================================================================

    // JitVsaFn: JIT-compiled function pointer for VSA operations
    // Takes two HybridBigInt pointers and writes result to first pointer
    // Signature: fn(*HybridBigInt, *HybridBigInt) -> void
    pub const JitVsaFn = *const fn (*anyopaque, *anyopaque) void;

    // JitSimilarityFn: JIT-compiled function pointer for similarity
    // Takes two HybridBigInt pointers and returns f64 similarity score
    // Signature: fn(*HybridBigInt, *HybridBigInt) -> f64
    pub const JitSimilarityFn = *const fn (*anyopaque, *anyopaque) f64;

    // ========================================================================
    // 2. JIT Compiler Type
    // ========================================================================

    // JitCompiler: Code generation engine for ternary operations
    // Generates platform-specific machine code for VSA operations
    // Manages code buffer, executable memory allocation, and function finalization
    pub struct JitCompiler {
        code_buffer : []u8,        // Generated machine code bytes
        allocator_id : u16,          // Allocator identifier (implementation detail)
        exec_memory : ?[]u8,        // Executable memory region (mmap'd)
    }

    // ========================================================================
    // 3. JIT Cache Type
    // ========================================================================

    // JitCache: Compilation cache for dimension-specific operations
    // Caches compiled functions by dimension to avoid redundant compilation
    // Maintains compiler instance for on-demand compilation
    pub struct JitCache {
        bind_cache : map<usize, JitVsaFn>,       // Cached bind functions by dimension
        compiler : JitCompiler,                    // Compiler instance for compilation
        allocator_id : u16,                       // Allocator identifier
    }

    // ========================================================================
    // 4. VSA Operation Types (for JIT compilation)
    // ========================================================================

    // VsaOperation: Enumeration of VSA operations to compile
    // Different operations require different code generation strategies
    pub const VsaOperation = enum(u8) {
        bind,           // Element-wise multiplication (bind)
        bundle,         // Element-wise sum with threshold (bundle)
        dot_product,    // Dot product for similarity
    };

    // ========================================================================
    // 5. JIT Compiler Functions
    // ========================================================================

    // initCompiler(allocator_id: u16) -> JitCompiler
    // Create a new JIT compiler instance
    // Returns initialized JitCompiler with empty code buffer
    // Complexity: O(1)
    pub fn initCompiler(allocator_id: u16) -> JitCompiler;

    // deinitCompiler(compiler: &JitCompiler)
    // Destroy JIT compiler and free resources
    // Releases code buffer and executable memory
    // Complexity: O(1) + memory deallocation
    pub fn deinitCompiler(compiler: &JitCompiler);

    // resetCompiler(compiler: &JitCompiler)
    // Reset code buffer for new compilation
    // Retains allocated capacity but clears content
    // Complexity: O(n) where n = current code buffer size
    pub fn resetCompiler(compiler: &JitCompiler);

    // compileOperation(compiler: &JitCompiler, op: VsaOperation, dimension: usize) -> usize
    // Compile a VSA operation for given dimension
    // Returns code size in bytes of generated code
    // Generates platform-specific machine code for the operation
    // Complexity: O(dimension) for code generation
    pub fn compileOperation(compiler: &JitCompiler, op: VsaOperation, dimension: usize) -> usize;

    // finalizeCompiler(compiler: &JitCompiler) -> ?JitVsaFn
    // Make generated code executable and return function pointer
    // Allocates executable memory, copies code, sets permissions
    // Returns null pointer if code buffer is empty
    // Complexity: O(1) for mmap + copy + mprotect
    pub fn finalizeCompiler(compiler: &JitCompiler) -> ?JitVsaFn;

    // codeSize(compiler: &JitCompiler) -> usize
    // Get current size of generated code
    // Returns byte count of code buffer
    // Complexity: O(1)
    pub fn codeSize(compiler: &JitCompiler) -> usize;

    // ========================================================================
    // 6. JIT Cache Functions
    // ========================================================================

    // initCache(allocator_id: u16) -> JitCache
    // Create a new JIT cache instance
    // Returns initialized JitCache with empty cache and compiler
    // Complexity: O(1)
    pub fn initCache(allocator_id: u16) -> JitCache;

    // deinitCache(cache: &JitCache)
    // Destroy JIT cache and free all cached functions
    // Releases compiler instance and clears cache map
    // Complexity: O(n) where n = cached functions
    pub fn deinitCache(cache: &JitCache);

    // getOrCompile(cache: &JitCache, op: VsaOperation, dimension: usize) -> ?JitVsaFn
    // Get cached function or compile if not cached
    // Returns function pointer or compiles new function if needed
    // Complexity: O(1) for cache hit, O(dimension) for compile
    pub fn getOrCompile(cache: &JitCache, op: VsaOperation, dimension: usize) -> ?JitVsaFn;

    // ========================================================================
    // 7. High-Level JIT API
    // ========================================================================

    // jitBind(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt)
    // Execute JIT-accelerated bind operation
    // Ensures operands are in unpacked mode, gets or compiles function, executes
    // Complexity: O(dimension) for compile (cached: O(1))
    pub fn jitBind(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt);

    // jitBundle(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt)
    // Execute JIT-accelerated bundle operation
    // Ensures operands are in unpacked mode, gets or compiles function, executes
    // Complexity: O(dimension) for compile (cached: O(1))
    pub fn jitBundle(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt);

    // jitDotProduct(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt) -> f64
    // Execute JIT-accelerated dot product operation
    // Ensures operands are in unpacked mode, gets or compiles function, executes
    // Returns dot product as f64 similarity score
    // Complexity: O(dimension) for compile (cached: O(1))
    pub fn jitDotProduct(cache: &JitCache, a: &HybridBigInt, b: &HybridBigInt) -> f64;

    // ========================================================================
    // TDD - Tests
    // ========================================================================

    test jit_compiler_init_creates_valid_compiler
        // Verify: initCompiler returns valid compiler
        given compiler = initCompiler(0)
        then compiler.code_buffer.len() == 0

    test jit_compiler_reset_clears_buffer
        // Verify: resetCompiler clears code buffer
        given compiler = initCompiler(0)
        and compileOperation(&compiler, .bind, 16)
        when resetCompiler(&compiler)
        then compiler.code_buffer.len() == 0

    test jit_compile_operation_generates_code
        // Verify: compileOperation generates code for bind operation
        given compiler = initCompiler(0)
        when size = compileOperation(&compiler, .bind, 32)
        then size > 0

    test jit_finalize_returns_function_ptr
        // Verify: finalizeCompiler creates executable function
        given compiler = initCompiler(0)
        and compileOperation(&compiler, .bind, 16)
        when func = finalizeCompiler(&compiler)
        then func != null

    test jit_cache_init_creates_valid_cache
        // Verify: initCache returns valid cache
        given cache = initCache(0)
        then cache.compiler.code_buffer.len() == 0

    test jit_cache_deinit_clears_resources
        // Verify: deinitCache clears cache
        given cache = initCache(0)
        and _ = getOrCompile(&cache, .bind, 16)
        when deinitCache(&cache)
        then cache.compiler.code_buffer.len() == 0

    test jit_cache_hit_returns_cached_function
        // Verify: getOrCompile returns cached function on second call
        given cache = initCache(0)
        and func1 = getOrCompile(&cache, .bind, 16)
        and func2 = getOrCompile(&cache, .bind, 16)
        then func1 == func2

    test jit_cache_miss_compiles_new_function
        // Verify: getOrCompile compiles on cache miss
        given cache = initCache(0)
        and func1 = getOrCompile(&cache, .bind, 16)
        and func2 = getOrCompile(&cache, .dot_product, 16)
        then func1 != func2

    test jit_dot_product_returns_f64
        // Verify: jitDotProduct returns f64 similarity score
        given cache = initCache(0)
        and _ = getOrCompile(&cache, .dot_product, 16)
        when result = jitDotProduct(&cache, a_dummy, b_dummy)
        then result > 0.0 or result < 0.0

    // ========================================================================
    // TDD - Invariants
    // ========================================================================

    invariant jit_compiler_code_buffer_allocated
        // Verify: JitCompiler code buffer is initialized
        // Compiler must have valid code buffer
        assert true;

    invariant jit_compiler_executable_memory_protected
        // Verify: Executable memory is set to read+execute only
        // Finalized code must be in non-writable executable region
        assert true;

    invariant jit_cache_keyed_by_dimension
        // Verify: JIT cache is keyed by dimension
        // Same dimension returns same function, different dimension may compile new
        assert true;

    invariant jit_cache_preserves_function_pointers
        // Verify: Cached functions remain valid across cache operations
        // Function pointers from cache must be valid until cache deinit
        assert true;

    invariant vsa_operation_enum_valid
        // Verify: VsaOperation enum has valid values
        // bind, bundle, dot_product must be distinct
        assert true;

    invariant jit_function_signatures_compatible
        // Verify: JIT function signatures match expected calling convention
        // JitVsaFn takes two HybridBigInt pointers
        assert true;

    // ========================================================================
    // TDD - Benchmarks
    // ========================================================================

    bench jit_compile_bind_latency
        // Measure: cycles for compiling bind operation (dimension=32)
        // Target: < 1000 cycles for code generation
        @setEvalBranchQuota(10000);
        var compiler = initCompiler(0);
        _ = compileOperation(&compiler, .bind, 32);
        _ = compiler;

    bench jit_compile_bundle_latency
        // Measure: cycles for compiling bundle operation (dimension=32)
        // Target: < 1500 cycles for code generation (more complex)
        @setEvalBranchQuota(10000);
        var compiler = initCompiler(0);
        _ = compileOperation(&compiler, .bundle, 32);
        _ = compiler;

    bench jit_compile_dot_product_latency
        // Measure: cycles for compiling dot product (dimension=32)
        // Target: < 2000 cycles for code generation (most complex)
        @setEvalBranchQuota(10000);
        var compiler = initCompiler(0);
        _ = compileOperation(&compiler, .dot_product, 32);
        _ = compiler;

    bench jit_cache_get_hit_latency
        // Measure: cycles for cache hit (function already compiled)
        // Target: < 100 cycles (hash map lookup)
        @setEvalBranchQuota(10000);
        var cache = initCache(0);
        _ = getOrCompile(&cache, .bind, 32);
        _ = getOrCompile(&cache, .bind, 32);
        _ = cache;

    bench jit_cache_get_miss_latency
        // Measure: cycles for cache miss (compilation required)
        // Target: < 1500 cycles (compile + cache insert)
        @setEvalBranchQuota(10000);
        var cache = initCache(0);
        _ = getOrCompile(&cache, .bind, 32);
        _ = cache;

    bench jit_finalize_latency
        // Measure: cycles for finalizing compiled code
        // Target: < 500 cycles (mmap + copy + mprotect)
        @setEvalBranchQuota(10000);
        var compiler = initCompiler(0);
        _ = compileOperation(&compiler, .bind, 32);
        _ = finalizeCompiler(&compiler);

    bench jit_bind_execution_latency
        // Measure: cycles for executing JIT-compiled bind (dimension=32)
        // Target: < 100 cycles (native call overhead)
        @setEvalBranchQuota(10000);
        var cache = initCache(0);
        var func = getOrCompile(&cache, .bind, 32);
        _ = func(dummy_ptr, dummy_ptr);
        _ = func;

    bench jit_dot_product_execution_latency
        // Measure: cycles for executing JIT-compiled dot product (dimension=32)
        // Target: < 500 cycles (native loop)
        @setEvalBranchQuota(10000);
        var cache = initCache(0);
        var func = getOrCompile(&cache, .dot_product, 32);
        _ = func(dummy_ptr, dummy_ptr);
        _ = func;
}

// specs/shell/schema.t27
// Shell Types Specification
// phi^2 + 1/phi^2 = 3 | TRINITY

module Shell {
    use base::types;

    // ====================================================================
    // Shell Types
    // ====================================================================

    // ShellType represents the type of shell
    enum ShellType {
        Bash = 0,
        Zsh = 1,
        Fish = 2,
        Dash = 3,
        Sh = 4,
        Pwsh = 5,
        PowerShell = 6,
        Cmd = 7,
        Unknown = 8,
    }

    // Platform represents the operating system platform
    enum Platform {
        Darwin = 0,
        Linux = 1,
        Windows = 2,
    }

    // ====================================================================
    // Process Types
    // ====================================================================

    // ProcessStatus represents the status of a process
    enum ProcessStatus {
        Running = 0,
        Exited = 1,
        Signaled = 2,
        Stopped = 3,
    }

    // ProcessInfo represents information about a process
    struct ProcessInfo {
        pid: u32,               // Process ID
        command: str,           // Command that started the process
        status: ProcessStatus,   // Current status
        exitCode: i32?,         // Exit code if exited
        signal: u32?,           // Signal that terminated process
        startTime: u64,         // When the process started
        endTime: u64?,          // When the process ended
    }

    // ProcessOptions represents options for spawning a process
    struct ProcessOptions {
        cwd: str?,              // Working directory
        env: [str: str]?,       // Environment variables
        timeout: u64?,          // Timeout in milliseconds
        stdin: str?,            // Input to send to stdin
        captureOutput: bool,    // Whether to capture stdout/stderr
        abort: bool?,           // Whether abort signal should terminate
    }

    // ProcessResult represents the result of a process
    struct ProcessResult {
        exitCode: i32,          // Exit code
        stdout: str,            // Standard output
        stderr: str,            // Standard error
        success: bool,          // Whether the process succeeded
        timedOut: bool,         // Whether the process timed out
        duration: u64,          // Duration in milliseconds
    }

    // ====================================================================
    // Shell Properties
    // ====================================================================

    // ShellProperties represents properties of a shell
    struct ShellProperties {
        path: str,              // Full path to the shell
        name: str,              // Shell name
        shellType: ShellType,   // Type of shell
        isLogin: bool,          // Whether it's a login shell
        isPosix: bool,          // Whether it's POSIX compliant
        isBlacklisted: bool,    // Whether it's blacklisted
    }

    // ====================================================================
    // Environment Types
    // ====================================================================

    // EnvVar represents an environment variable
    struct EnvVar {
        name: str,              // Variable name
        value: str,             // Variable value
    }

    // ====================================================================
    // Constants
    // ====================================================================

    const SIGKILL_TIMEOUT_MS: u32 = 200;
    const SHELL_ENV_VAR: str = "SHELL";

    // ====================================================================
    // Error Types
    // ====================================================================

    // ShellError represents errors in shell operations
    enum ShellError {
        NotFound = 0,
        PermissionDenied = 1,
        Timeout = 2,
        Signal = 3,
        InvalidCommand = 4,
        ProcessError = 5,
        EnvironmentError = 6,
    }

    // ====================================================================
    // Helper Functions
    // ====================================================================

    // is_posix checks if a shell type is POSIX compliant
    fn is_posix(shellType: ShellType) -> bool {
        return shellType == ShellType::Bash
            || shellType == ShellType::Zsh
            || shellType == ShellType::Dash
            || shellType == ShellType::Sh;
    }

    // is_login checks if a shell type is typically a login shell
    fn is_login(shellType: ShellType) -> bool {
        return shellType == ShellType::Bash
            || shellType == ShellType::Zsh
            || shellType == ShellType::Fish
            || shellType == ShellType::Dash
            || shellType == ShellType::Sh;
    }

    // is_blacklisted checks if a shell is blacklisted
    fn is_blacklisted(shellType: ShellType) -> bool {
        return shellType == ShellType::Fish || shellType == ShellType::Nu;
    }

    // is_success checks if a process result indicates success
    fn is_success(result: ProcessResult) -> bool {
        return result.exitCode == 0 && !result.timedOut;
    }

    // ====================================================================
    // Tests
    // ====================================================================

    test "shell_type_values" {
        assert(ShellType::Bash as u32 == 0);
        assert(ShellType::Zsh as u32 == 1);
        assert(ShellType::Fish as u32 == 2);
        assert(ShellType::Dash as u32 == 3);
        assert(ShellType::Sh as u32 == 4);
        assert(ShellType::Pwsh as u32 == 5);
        assert(ShellType::PowerShell as u32 == 6);
        assert(ShellType::Cmd as u32 == 7);
        assert(ShellType::Unknown as u32 == 8);
    }

    test "platform_values" {
        assert(Platform::Darwin as u32 == 0);
        assert(Platform::Linux as u32 == 1);
        assert(Platform::Windows as u32 == 2);
    }

    test "process_status_values" {
        assert(ProcessStatus::Running as u32 == 0);
        assert(ProcessStatus::Exited as u32 == 1);
        assert(ProcessStatus::Signaled as u32 == 2);
        assert(ProcessStatus::Stopped as u32 == 3);
    }

    test "shell_error_values" {
        assert(ShellError::NotFound as u32 == 0);
        assert(ShellError::PermissionDenied as u32 == 1);
        assert(ShellError::Timeout as u32 == 2);
        assert(ShellError::Signal as u32 == 3);
        assert(ShellError::InvalidCommand as u32 == 4);
        assert(ShellError::ProcessError as u32 == 5);
        assert(ShellError::EnvironmentError as u32 == 6);
    }

    test "process_info_creation" {
        var info = ProcessInfo {
            pid = 12345,
            command = "ls -la",
            status = ProcessStatus::Running,
            exitCode = null,
            signal = null,
            startTime = 1234567890,
            endTime = null,
        };
        assert(info.pid == 12345);
        assert(info.command == "ls -la");
        assert(info.status == ProcessStatus::Running);
    }

    test "process_info_exited" {
        var info = ProcessInfo {
            pid = 12345,
            command = "ls -la",
            status = ProcessStatus::Exited,
            exitCode = 0,
            signal = null,
            startTime = 1234567890,
            endTime = 1234567900,
        };
        assert(info.status == ProcessStatus::Exited);
        assert(info.exitCode == 0);
        assert(info.endTime == 1234567900);
    }

    test "process_options_default" {
        var opts = ProcessOptions {
            cwd = null,
            env = null,
            timeout = null,
            stdin = null,
            captureOutput = true,
            abort = null,
        };
        assert(opts.captureOutput);
        assert(opts.cwd == null);
    }

    test "process_options_full" {
        var env: [str: str] = { "PATH": "/usr/bin", "HOME": "/home/user" };
        var opts = ProcessOptions {
            cwd = "/tmp",
            env = env,
            timeout = 5000,
            stdin = "input",
            captureOutput = false,
            abort = true,
        };
        assert(opts.cwd == "/tmp");
        assert(opts.timeout == 5000);
        assert(opts.stdin == "input");
    }

    test "process_result_success" {
        var result = ProcessResult {
            exitCode = 0,
            stdout = "output",
            stderr = "",
            success = true,
            timedOut = false,
            duration = 100,
        };
        assert(result.success);
        assert(!result.timedOut);
        assert(result.exitCode == 0);
    }

    test "process_result_failure" {
        var result = ProcessResult {
            exitCode = 1,
            stdout = "",
            stderr = "error",
            success = false,
            timedOut = false,
            duration = 50,
        };
        assert(!result.success);
        assert(result.exitCode == 1);
    }

    test "process_result_timeout" {
        var result = ProcessResult {
            exitCode = 124,
            stdout = "",
            stderr = "timeout",
            success = false,
            timedOut = true,
            duration = 5000,
        };
        assert(result.timedOut);
        assert(result.exitCode == 124);
    }

    test "shell_properties_bash" {
        var props = ShellProperties {
            path = "/bin/bash",
            name = "bash",
            shellType = ShellType::Bash,
            isLogin = true,
            isPosix = true,
            isBlacklisted = false,
        };
        assert(props.shellType == ShellType::Bash);
        assert(props.isPosix);
        assert(props.isLogin);
        assert(!props.isBlacklisted);
    }

    test "shell_properties_fish" {
        var props = ShellProperties {
            path = "/usr/local/bin/fish",
            name = "fish",
            shellType = ShellType::Fish,
            isLogin = true,
            isPosix = false,
            isBlacklisted = true,
        };
        assert(props.shellType == ShellType::Fish);
        assert(!props.isPosix);
        assert(props.isBlacklisted);
    }

    test "env_var_creation" {
        var envVar = EnvVar {
            name = "PATH",
            value = "/usr/bin:/bin",
        };
        assert(envVar.name == "PATH");
        assert(envVar.value == "/usr/bin:/bin");
    }

    test "constants_values" {
        assert(SIGKILL_TIMEOUT_MS == 200);
        assert(SHELL_ENV_VAR == "SHELL");
    }

    test "is_posix_true" {
        assert(is_posix(ShellType::Bash));
        assert(is_posix(ShellType::Zsh));
        assert(is_posix(ShellType::Dash));
        assert(is_posix(ShellType::Sh));
    }

    test "is_posix_false" {
        assert(!is_posix(ShellType::Fish));
        assert(!is_posix(ShellType::Pwsh));
        assert(!is_posix(ShellType::PowerShell));
        assert(!is_posix(ShellType::Cmd));
    }

    test "is_login_true" {
        assert(is_login(ShellType::Bash));
        assert(is_login(ShellType::Zsh));
        assert(is_login(ShellType::Fish));
        assert(is_login(ShellType::Dash));
        assert(is_login(ShellType::Sh));
    }

    test "is_login_false" {
        assert(!is_login(ShellType::Pwsh));
        assert(!is_login(ShellType::PowerShell));
        assert(!is_login(ShellType::Cmd));
    }

    test "is_blacklisted_true" {
        assert(is_blacklisted(ShellType::Fish));
    }

    test "is_blacklisted_false" {
        assert(!is_blacklisted(ShellType::Bash));
        assert(!is_blacklisted(ShellType::Zsh));
        assert(!is_blacklisted(ShellType::Sh));
    }

    test "is_success_true" {
        var result = ProcessResult {
            exitCode = 0,
            stdout = "",
            stderr = "",
            success = true,
            timedOut = false,
            duration = 10,
        };
        assert(is_success(result));
    }

    test "is_success_false_exit_code" {
        var result = ProcessResult {
            exitCode = 1,
            stdout = "",
            stderr = "",
            success = false,
            timedOut = false,
            duration = 10,
        };
        assert(!is_success(result));
    }

    test "is_success_false_timeout" {
        var result = ProcessResult {
            exitCode = 0,
            stdout = "",
            stderr = "",
            success = false,
            timedOut = true,
            duration = 5000,
        };
        assert(!is_success(result));
    }
}

// registry.t27 -- Skill Registry JSON Structure (ADR-002)
// Defines the structure for tri skill workflow registry
// phi^2 + 1/phi^2 = 3 | TRINITY

module skill_registry {
    // =====================================================================
    // Skill Registry Structure
    // =====================================================================

    pub const RegistryPath: []const u8 = ".trinity/skills/registry.json";

    // Skill status enum
    pub const SkillStatus = enum(u8) {
        Active = 0,      // Skill is currently being worked on
        Sealed = 1,      // Skill has been sealed, ready for commit/push
        Paused = 2,      // Skill work is paused
        Blocked = 3,     // Skill is blocked, cannot proceed
        Completed = 4,   // Skill work is complete
    };

    // Skill kind enum
    pub const SkillKind = enum(u8) {
        Feature = 0,     // New feature implementation
        Bugfix = 1,      // Bug fix
        Hotfix = 2,      // Urgent hotfix (limited scope)
        Recovery = 3,    // Recovery from previous failure
        Refactor = 4,    // Code refactoring
    };

    // Skill verdict enum
    pub const SkillVerdict = enum(u8) {
        NotToxic = 0,    // Skill is safe to proceed
        Toxic = 1,       // Skill has toxic elements, must be fixed
    };

    // Skill metadata
    pub const SkillMetadata = struct {
        title: []const u8,
        author: []const u8,
        priority: []const u8,  // P0, P1, P2, P3
        tags: [][]const u8,
    };

    // Skill structure
    pub const Skill = struct {
        id: []const u8,                // Unique skill identifier
        status: SkillStatus,          // Current status
        kind: SkillKind,              // Type of work
        issue: ?[]const u8,           // Bound GitHub issue ID
        branch: []const u8,           // Git branch
        created_at: []const u8,       // Creation timestamp
        updated_at: []const u8,       // Last update timestamp
        sealed_at: ?[]const u8,       // Seal timestamp
        commit: ?[]const u8,          // Last commit hash
        commit_at: ?[]const u8,       // Commit timestamp
        pushed: bool,                 // Whether pushed to remote
        pushed_at: ?[]const u8,       // Push timestamp
        verdict: ?SkillVerdict,       // Toxicity verdict
        verdict_at: ?[]const u8,      // Verdict timestamp
        seal_hash: ?[]const u8,       // Hash of sealed state
        artifacts: []const u8,         // Artifact list
        metadata: SkillMetadata,      // Additional metadata
    };

    // Skill Registry structure
    pub const SkillRegistry = struct {
        version: []const u8,
        skills: []Skill,
    };

    // =====================================================================
    // Policy Matrix (for git push validation)
    // =====================================================================

    // Recovery skill requirements:
    //   - Minimum 3 checkpoints
    //   - Spec must be modified
    //   - Docs must be modified
    //   - Verdict must be NOT TOXIC

    // Hotfix skill requirements:
    //   - Minimum 1 checkpoint
    //   - Changes only in "fix only" areas (no breaking changes)
    //   - Verdict must be NOT TOXIC

    // Feature skill requirements:
    //   - At least 1 test (per TDD contract)
    //   - Spec has at least one test/invariant
    //   - Verdict must be NOT TOXIC

    // =====================================================================
    // Registry JSON Schema
    // =====================================================================

    /*
    {
      "$schema": "http://json-schema.org/draft-07/schema#",
      "type": "object",
      "required": ["version", "skills"],
      "properties": {
        "version": {
          "type": "string",
          "pattern": "^\\d+\\.\\d+$"
        },
        "skills": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["id", "status", "kind", "branch", "created_at", "updated_at"],
            "properties": {
              "id": {
                "type": "string",
                "pattern": "^skill-\\d+$"
              },
              "status": {
                "type": "string",
                "enum": ["active", "sealed", "paused", "blocked", "completed"]
              },
              "kind": {
                "type": "string",
                "enum": ["feature", "bugfix", "hotfix", "recovery", "refactor"]
              },
              "issue": { "type": "string" },
              "branch": { "type": "string" },
              "created_at": { "type": "string", "format": "date-time" },
              "updated_at": { "type": "string", "format": "date-time" },
              "sealed_at": { "type": "string", "format": "date-time" },
              "commit": {
                "type": "string",
                "pattern": "^[a-f0-9]{40}$"
              },
              "commit_at": { "type": "string", "format": "date-time" },
              "pushed": { "type": "boolean" },
              "pushed_at": { "type": "string", "format": "date-time" },
              "verdict": {
                "type": "string",
                "enum": ["NOT TOXIC", "TOXIC"]
              },
              "verdict_at": { "type": "string", "format": "date-time" },
              "seal_hash": { "type": "string" },
              "artifacts": { "type": "string" },
              "metadata": {
                "type": "object",
                "properties": {
                  "title": { "type": "string" },
                  "author": { "type": "string" },
                  "priority": {
                    "type": "string",
                    "enum": ["P0", "P1", "P2", "P3"]
                  },
                  "tags": {
                    "type": "array",
                    "items": { "type": "string" }
                  }
                }
              }
            }
          }
        }
      }
    }
    */

    // =====================================================================
    // Helper Functions
    // =====================================================================

    // Create empty skill registry
    pub fn create_registry() SkillRegistry {
        return SkillRegistry{
            .version = "1.0",
            .skills = &[_]Skill{},
        };
    }

    // Create minimal skill with required fields
    pub fn create_skill(id: []const u8, kind: SkillKind, branch: []const u8) Skill {
        const now = "2026-04-04T00:00:00Z";
        return Skill{
            .id = id,
            .status = SkillStatus.Active,
            .kind = kind,
            .issue = null,
            .branch = branch,
            .created_at = now,
            .updated_at = now,
            .sealed_at = null,
            .commit = null,
            .commit_at = null,
            .pushed = false,
            .pushed_at = null,
            .verdict = null,
            .verdict_at = null,
            .seal_hash = null,
            .artifacts = "",
            .metadata = SkillMetadata{
                .title = "",
                .author = "",
                .priority = "P1",
                .tags = &[_][]const u8{},
            },
        };
    }

    // Check if skill is ready for commit
    pub fn can_commit(skill: Skill) bool {
        return skill.status == SkillStatus.Sealed;
    }

    // Check if skill is ready for push
    pub fn can_push(skill: Skill) bool {
        return skill.status == SkillStatus.Sealed and
               skill.commit != null and
               skill.verdict == SkillVerdict.NotToxic;
    }
}

