// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/memory.t27
// Memory (BRAM/DRAM/ROM) Abstraction for Trinity T27 FPGA HIR
// Defines block memory primitives with read/write ports
// Uses flat arrays + count fields (parser-compatible, no Vec/generics)
// phi^2 + 1/phi^2 = 3 | TRINITY

module Memory {

    // === Memory kind ===

    pub const MemKind = enum(i8) {
        bram = 0,
        dram = 1,
        rom = 2,
    };

    // === Port kind (read vs write vs read-write) ===

    pub const MemPortKind = enum(i8) {
        read_port = 0,
        write_port = 1,
        readwrite_port = 2,
    };

    // === Latency (combinational vs registered) ===

    pub const MemLatency = enum(i8) {
        comb_read = 0,
        reg_read = 1,
    };

    // === Memory port descriptor ===

    pub struct MemPort {
        name : &str,
        kind : i8,
        addr_width : u32,
        data_width : u32,
        latency : i8,
    }

    // === Memory block descriptor ===

    pub const MAX_MEM_PORTS : u32 = 8;

    pub struct MemDesc {
        name : &str,
        kind : i8,
        depth : u32,
        data_width : u32,
        addr_width : u32,
        ports : [8]MemPort,
        port_count : u32,
    }

    // === Constructor helpers ===

    fn empty_mem_port() -> MemPort {
        return MemPort{
            .name = "",
            .kind = 0,
            .addr_width = 0,
            .data_width = 0,
            .latency = 0,
        };
    }

    fn make_mem_port(name: &str, kind: i8, addr_width: u32, data_width: u32) -> MemPort {
        return MemPort{
            .name = name,
            .kind = kind,
            .addr_width = addr_width,
            .data_width = data_width,
            .latency = 0,
        };
    }

    fn empty_mem(name: &str, kind: i8) -> MemDesc {
        return MemDesc{
            .name = name,
            .kind = kind,
            .depth = 0,
            .data_width = 0,
            .addr_width = 0,
            .ports = [empty_mem_port(); 8],
            .port_count = 0,
        };
    }

    fn make_bram(name: &str, depth: u32, data_width: u32) -> MemDesc {
        var addr_width : u32 = 0;
        var d : u32 = depth;
        while (d > 1) {
            addr_width = addr_width + 1;
            d = d / 2;
        }
        if (addr_width == 0) {
            addr_width = 1;
        }
        return MemDesc{
            .name = name,
            .kind = 0,
            .depth = depth,
            .data_width = data_width,
            .addr_width = addr_width,
            .ports = [empty_mem_port(); 8],
            .port_count = 0,
        };
    }

    fn make_rom(name: &str, depth: u32, data_width: u32) -> MemDesc {
        var addr_width : u32 = 0;
        var d : u32 = depth;
        while (d > 1) {
            addr_width = addr_width + 1;
            d = d / 2;
        }
        if (addr_width == 0) {
            addr_width = 1;
        }
        return MemDesc{
            .name = name,
            .kind = 2,
            .depth = depth,
            .data_width = data_width,
            .addr_width = addr_width,
            .ports = [empty_mem_port(); 8],
            .port_count = 0,
        };
    }

    fn add_read_port(mem: MemDesc, name: &str) -> MemDesc {
        var result = mem;
        if (result.port_count < 8) {
            result.ports[result.port_count] = make_mem_port(name, 0, result.addr_width, result.data_width);
            result.port_count = result.port_count + 1;
        }
        return result;
    }

    fn add_write_port(mem: MemDesc, name: &str) -> MemDesc {
        var result = mem;
        if (result.port_count < 8) {
            result.ports[result.port_count] = make_mem_port(name, 1, result.addr_width, result.data_width);
            result.port_count = result.port_count + 1;
        }
        return result;
    }

    fn add_rw_port(mem: MemDesc, name: &str) -> MemDesc {
        var result = mem;
        if (result.port_count < 8) {
            result.ports[result.port_count] = make_mem_port(name, 2, result.addr_width, result.data_width);
            result.port_count = result.port_count + 1;
        }
        return result;
    }

    // === Query functions ===

    fn port_count(mem: MemDesc) -> u32 {
        return mem.port_count;
    }

    fn total_bits(mem: MemDesc) -> u32 {
        return mem.depth * mem.data_width;
    }

    fn has_read_port(mem: MemDesc) -> bool {
        var i : u32 = 0;
        while (i < mem.port_count) {
            if (mem.ports[i].kind == 0 or mem.ports[i].kind == 2) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn has_write_port(mem: MemDesc) -> bool {
        var i : u32 = 0;
        while (i < mem.port_count) {
            if (mem.ports[i].kind == 1 or mem.ports[i].kind == 2) {
                return true;
            }
            i = i + 1;
        }
        return false;
    }

    fn is_rom(mem: MemDesc) -> bool {
        return mem.kind == 2;
    }

    fn is_bram(mem: MemDesc) -> bool {
        return mem.kind == 0;
    }

    fn addr_width(mem: MemDesc) -> u32 {
        return mem.addr_width;
    }

    // === BRAM18E1 resource estimation ===

    fn bram18_count(mem: MemDesc) -> u32 {
        var bits : u32 = mem.depth * mem.data_width;
        var count : u32 = bits / 18432;
        if (bits % 18432 > 0) {
            count = count + 1;
        }
        return count;
    }

    // === Validation ===

    fn validate_mem(mem: MemDesc) -> u32 {
        var errors : u32 = 0;

        if (mem.name == "") {
            errors = errors + 1;
        }

        if (mem.depth == 0) {
            errors = errors + 1;
        }

        if (mem.data_width == 0) {
            errors = errors + 1;
        }

        if (mem.kind == 2 and has_write_port(mem)) {
            errors = errors + 1;
        }

        return errors;
    }

    // === Tests ===

    test empty_mem_has_no_ports
        given m = empty_mem("test", 0)
        then port_count(m) == 0

    test make_bram_has_depth
        given m = make_bram("ram1", 1024, 32)
        then m.depth == 1024
        and m.data_width == 32
        and m.addr_width == 10

    test make_bram_small
        given m = make_bram("ram2", 4, 8)
        then m.addr_width == 2

    test make_bram_single
        given m = make_bram("ram3", 1, 16)
        then m.addr_width == 1

    test add_read_port_increments
        given m = make_bram("ram1", 256, 16)
        and m2 = add_read_port(m, "rda")
        then port_count(m2) == 1
        and has_read_port(m2) == true
        and has_write_port(m2) == false

    test add_write_port_increments
        given m = make_bram("ram1", 256, 16)
        and m2 = add_write_port(m, "wra")
        then port_count(m2) == 1
        and has_write_port(m2) == true
        and has_read_port(m2) == false

    test add_rw_port
        given m = make_bram("ram1", 256, 16)
        and m2 = add_rw_port(m, "rwa")
        then port_count(m2) == 1
        and has_read_port(m2) == true
        and has_write_port(m2) == true

    test is_rom
        given m = make_rom("rom1", 512, 8)
        then is_rom(m) == true
        and is_bram(m) == false

    test total_bits
        given m = make_bram("ram1", 1024, 32)
        then total_bits(m) == 32768

    test bram18_count_small
        given m = make_bram("ram1", 1024, 18)
        then bram18_count(m) == 1

    test bram18_count_large
        given m = make_bram("ram1", 4096, 36)
        then bram18_count(m) >= 8

    test validate_ok
        given m = make_bram("ram1", 256, 16)
        and m2 = add_read_port(m, "rda")
        and errors = validate_mem(m2)
        then errors == 0

    test validate_empty_name
        given m = empty_mem("", 0)
        and m2 = MemDesc{.name = "", .kind = 0, .depth = 16, .data_width = 8, .addr_width = 4, .ports = [empty_mem_port(); 8], .port_count = 0}
        and errors = validate_mem(m2)
        then errors > 0

    test validate_zero_depth
        given m = MemDesc{.name = "x", .kind = 0, .depth = 0, .data_width = 8, .addr_width = 1, .ports = [empty_mem_port(); 8], .port_count = 0}
        and errors = validate_mem(m)
        then errors > 0

    test rom_with_write_port_invalid
        given m = make_rom("rom1", 256, 16)
        and m2 = add_write_port(m, "wra")
        and errors = validate_mem(m2)
        then errors > 0

    // === Invariants ===

    invariant bram_depth_positive
        given m = make_bram("inv", 256, 16)
        assert m.depth > 0

    invariant bram_data_width_positive
        given m = make_bram("inv", 256, 16)
        assert m.data_width > 0

    invariant addr_width_positive_for_nonzero_depth
        given m = make_bram("inv", 256, 16)
        assert m.addr_width > 0

    invariant total_bits_non_negative
        given m = make_bram("inv", 256, 16)
        assert total_bits(m) >= 0

    invariant port_count_within_bounds
        given m = make_bram("inv", 256, 16)
        and m2 = add_read_port(m, "rda")
        assert port_count(m2) <= 8

    invariant bram18_count_positive
        given m = make_bram("inv", 1024, 32)
        assert bram18_count(m) > 0

    // === Benchmarks ===

    bench bram18_count_latency
        measure: nanoseconds to bram18_count(make_bram("bench", 4096, 32))
        target: < 100ns
}

// phi^2 + 1/phi^2 = 3 | TRINITY

// SPDX-License-Identifier: Apache-2.0
// t27/specs/math/pellis_precision_verify.t27
// Arbitrary precision verification via GMP/MPFR reference
// NUMERIC-VERIF-001 -- Pre-registered checkpoint for CODATA 2026

module PellisPrecision {
    use math::constants;
    use math::sacred_physics;

    // =================================================================
    // 1. Golden Ratio at 100 Decimal Digits (pre-computed via GMP)
    // =========================================================================

    // phi = (1 + sqrt5) / 2 at 100 decimal places
    // Computed once via GMP/mpmath, sealed as constant
    // Reference: mpmath.mpf(1).sqrt(5) + 1) / 2 at 100 digits precision
    const PHI_100DIGITS : string = "1.61803398874989484820458683436563811772030917980576286213544862270526046281890244970720720418939113748475";

    // phi^-^1 = phi - 1 at 100 decimal places
    const PHI_INV_100DIGITS : string = "0.61803398874989484820458683436563811772030917980576286213544862270526046281890244970720720418939113748475";

    // =================================================================
    // 2. Pellis Closed Form at 50 Decimal Digits (pre-registered checkpoint)
    // =========================================================================

    // Pellis = 360/phi^2 - 2/phi^3 + (3phi)^-^5
    // Pre-registered for CODATA 2026/2030 comparison
    // Computed via GMP: 360/mp.mpf(phi**2) - 2/mp.mpf(phi**3) + (3*phi)**(-5)
    // 50 digits after the decimal point; refresh: python3 scripts/print_pellis_seal_decimal.py 55
    const PELLIS_50DIGITS : string = "137.03599916476563934505723564140907572836137437744729";

    // CODATA 2022 reference: 137.035999166(15)
    const ALPHA_INV_CODATA_2022 : string = "137.035999166";

    // f64-style fixed prefix (~=15 significant fractional digits; IEEE rounding)
    const PELLIS_FIRST_15_DIGITS : string = "137.035999164765";

    // =================================================================
    // 3. Verification Tests (string compare against pre-computed values)
    // =========================================================================

    struct PellisPrecisionResult {
        phi_f64          : f64,
        phi_100digits    : string,
        pellis_f64       : f64,
        pellis_50digits  : string,
        matches_prefix   : bool,
        digit_count_f64  : i32,
    }

    fn pellis_pre_registered_checkpoint() -> PellisPrecisionResult {
        const phi = sacred_physics::PHI;
        const phi_sq = phi * phi;
        const phi_cubed = phi * phi * phi;

        // Compute Pellis via f64 (NOT 50-digit accurate -- this test documents limit)
        const pellis_f64 = 360.0 / phi_sq - 2.0 / phi_cubed + (3.0 * phi).pow(-5.0);

        // Count significant decimal digits of f64 representation
        const digit_count = count_significant_digits(pellis_f64);

        // String representation for first 15 digits (f64 limit)
        const pellis_str = format(pellis_f64, ".15f");
        const matches = pellis_str.starts_with(PELLIS_FIRST_15_DIGITS);

        return PellisPrecisionResult{
            phi_f64 = phi,
            phi_100digits = PHI_100DIGITS,
            pellis_f64 = pellis_f64,
