    // Count significant decimal digits (digits after decimal point that are non-zero)
    fn count_significant_digits(x: f64) -> i32 {
        if x == 0.0 {
            return 0;
        }

        // Convert to string and count digits after decimal
        const s = format(x, ".15f");
        let count = 0;
        let found_decimal = false;
        let found_non_zero = false;

        for i in 0..len(s) {
            const c = s[i];
            if c == '.' {
                found_decimal = true;
            } else if found_decimal {
                if c != '0' {
                    found_non_zero = true;
                }
                if found_non_zero {
                    count = count + 1;
                }
            }
        }

        return count;
    }

