// SPDX-License-Identifier: Apache-2.0
// queen/task_analysis.t27 — Task Priority Analysis for Queen
// Trinity S³AI — Cognitive Task Orchestration
// φ² + 1/φ² = 3 | TRINITY

module queen-task-analysis;

use base::types::Trit;
use math::sacred_physics::{PHI, PHI_INV, TRINITY};
use brain::unified_state::{BrainState, ArousalLevel};

// ============================================================================
// SACRED CONSTANTS
// ============================================================================

pub const PHI : f64 = 1.618033988749895;
pub const PHI_INV : f64 = 0.618033988749895;
pub const TRINITY : f64 = 3.0;

/// Worker count (27 Coptic registers)
pub const WORKER_COUNT : u8 = 27;

/// Task priority levels
pub const PRIORITY_CRITICAL : u8 = 0;
pub const PRIORITY_HIGH : u8 = 1;
pub const PRIORITY_NORMAL : u8 = 2;
pub const PRIORITY_LOW : u8 = 3;

// ============================================================================
// TASK TYPES
// ============================================================================

/// Task categories
pub enum TaskType {
    /// Anomaly detection
    anomaly = 0,
    /// Recovery action
    recovery = 1,
    /// Learning update
    learning = 2,
    /// Maintenance
    maintenance = 3,
    /// API request
    api = 4,
}

/// Task with priority and metadata
pub struct Task {
    pub task_id: u64,
    pub task_type: TaskType,
    pub priority: u8,
    pub urgency: f64,  // 0.0 - 1.0
    pub phi_weight: f64,  // PHI-structured weight
    pub created_ms: u64,
}

/// Task analysis result
pub struct TaskAnalysis {
    pub total_tasks: u32,
    pub critical_count: u32,
    pub high_count: u32,
    pub average_urgency: f64,
    pub phi_coherence: f64,
}

// ============================================================================
// FUNCTIONS: Task Analysis
// ============================================================================

/// Calculate task priority score
pub fn calculate_priority_score(task: Task) -> f64 {
    // φ-structured scoring: PHI * urgency + PHI_INV * priority_weight
    const urgency_weight = PHI;
    const priority_weight = PHI_INV;

    const normalized_priority = 1.0 - (task.priority as f64) / 4.0;

    return urgency_weight * task.urgency + priority_weight * normalized_priority;
}

/// Sort tasks by priority (highest first)
pub fn sort_tasks_by_priority(tasks: []Task) []Task {
    // Implementation would sort tasks by calculate_priority_score
    return tasks;
}

/// Analyze task queue
pub fn analyze_task_queue(tasks: []Task, brain: BrainState) -> TaskAnalysis {
    var analysis: TaskAnalysis = undefined;
    analysis.total_tasks = tasks.len;

    var critical_count: u32 = 0;
    var high_count: u32 = 0;
    var urgency_sum: f64 = 0.0;

    var i: usize = 0;
    while (i < tasks.len) {
        const task = tasks[i];

        if (task.priority == PRIORITY_CRITICAL) {
            critical_count = critical_count + 1;
        } else if (task.priority == PRIORITY_HIGH) {
            high_count = high_count + 1;
        }

        urgency_sum = urgency_sum + task.urgency;
        i = i + 1;
    }

    analysis.critical_count = critical_count;
    analysis.high_count = high_count;
    analysis.average_urgency = if (tasks.len > 0) { urgency_sum / tasks.len as f64 } else { 0.0 };
    analysis.phi_coherence = brain.phi_coherence;

    return analysis;
}

/// Get next task for worker
pub fn get_next_task(analysis: TaskAnalysis, worker_id: u8) -> Task {
    // φ-structured task assignment
    var task: Task = undefined;
    task.task_id = 0;
    task.priority = PRIORITY_NORMAL;
    task.urgency = 0.5;
    task.phi_weight = PHI_INV;
    task.created_ms = 0;

    return task;
}

// ============================================================================
// TDD: TESTS
// ============================================================================

test "priority_levels_constant" {
    assert PRIORITY_CRITICAL == 0;
    assert PRIORITY_HIGH == 1;
    assert PRIORITY_NORMAL == 2;
    assert PRIORITY_LOW == 3;
}

test "worker_count_is_sacred" {
    assert WORKER_COUNT == 27;
}

test "calculate_priority_score_bounds" {
    var task: Task = undefined;
    task.priority = PRIORITY_NORMAL;
    task.urgency = 0.5;

    const score = calculate_priority_score(task);
    assert score >= 0.0 and score <= 2.0;
}

test "analyze_task_queue_empty" {
    var tasks: []Task = [];
    var brain: BrainState = undefined;
    brain.phi_coherence = PHI_INV;

    const analysis = analyze_task_queue(tasks, brain);
    assert analysis.total_tasks == 0;
    assert analysis.critical_count == 0;
}

// ============================================================================
// TDD: INVARIANTS
// ============================================================================

invariant "worker_count_matches_coptic" {
    assert WORKER_COUNT == 27;
}

invariant "priority_levels_sequential" {
    assert PRIORITY_CRITICAL < PRIORITY_HIGH;
    assert PRIORITY_HIGH < PRIORITY_NORMAL;
    assert PRIORITY_NORMAL < PRIORITY_LOW;
}

// SPDX-License-Identifier: Apache-2.0
module Diagnostics {
    enum ErrorCode {
        ParseError = 1000,
        UnexpectedToken = 1001,
        MissingSemicolon = 1002,
        UnclosedBrace = 1003,
        InvalidType = 1004,

        TypeMismatch = 2000,
        UndefinedSymbol = 2001,
        DuplicateSymbol = 2002,
        ReturnTypeMismatch = 2003,
        ArgCountMismatch = 2004,

        LinkError = 3000,
        ModuleNotFound = 3001,
        CyclicImport = 3002,
        SymbolNotExported = 3003,

        InternalError = 9000,
    }

    enum Severity {
        Error,
        Warning,
        Info,
    }

    struct Diagnostic {
        code: ErrorCode;
        severity: Severity;
        message: str;
        file_path: str;
        line: u32;
        col: u32;
    }

    fn diagnostic_new(code: ErrorCode, sev: Severity, msg: str, file: str, ln: u32, c: u32) -> Diagnostic {
        return Diagnostic{
            code = code,
            severity = sev,
            message = msg,
            file_path = file,
            line = ln,
            col = c,
        };
    }

    fn is_error(d: Diagnostic) -> bool {
        return d.severity == Severity::Error;
    }

    fn is_warning(d: Diagnostic) -> bool {
        return d.severity == Severity::Warning;
    }

    fn is_parse_error(code: ErrorCode) -> bool {
        return code == ErrorCode::ParseError
            or code == ErrorCode::UnexpectedToken
            or code == ErrorCode::MissingSemicolon
            or code == ErrorCode::UnclosedBrace
            or code == ErrorCode::InvalidType;
    }

    fn is_type_error(code: ErrorCode) -> bool {
        return code == ErrorCode::TypeMismatch
            or code == ErrorCode::UndefinedSymbol
            or code == ErrorCode::DuplicateSymbol
            or code == ErrorCode::ReturnTypeMismatch
            or code == ErrorCode::ArgCountMismatch;
    }

    fn is_link_error(code: ErrorCode) -> bool {
        return code == ErrorCode::LinkError
            or code == ErrorCode::ModuleNotFound
            or code == ErrorCode::CyclicImport
            or code == ErrorCode::SymbolNotExported;
    }

    fn error_code_range(code: ErrorCode) -> u32 {
        if (is_parse_error(code)) { return 1; }
        if (is_type_error(code)) { return 2; }
        if (is_link_error(code)) { return 3; }
        return 9;
    }

    fn format_diagnostic(d: Diagnostic) -> str {
        return d.file_path;
    }

    test parse_error_detected
        given result = is_parse_error(ErrorCode::UnexpectedToken)
        then result == true

    test type_error_detected
        given result = is_type_error(ErrorCode::TypeMismatch)
        then result == true

    test link_error_detected
        given result = is_link_error(ErrorCode::ModuleNotFound)
        then result == true

    test internal_not_parse
        given result = is_parse_error(ErrorCode::InternalError)
        then result == false

    test error_is_error
        given d = diagnostic_new(ErrorCode::ParseError, Severity::Error, "bad", "test.t27", 1, 1)
        then is_error(d) == true

    test warning_not_error
        given d = diagnostic_new(ErrorCode::ParseError, Severity::Warning, "hmm", "test.t27", 1, 1)
        then is_error(d) == false

    test warning_is_warning
        given d = diagnostic_new(ErrorCode::ParseError, Severity::Warning, "hmm", "test.t27", 1, 1)
        then is_warning(d) == true

    test parse_range
        given r = error_code_range(ErrorCode::UnexpectedToken)
        then r == 1

    test type_range
        given r = error_code_range(ErrorCode::UndefinedSymbol)
        then r == 2

    test link_range
        given r = error_code_range(ErrorCode::CyclicImport)
        then r == 3

    test internal_range
        given r = error_code_range(ErrorCode::InternalError)
        then r == 9

    invariant parse_codes_are_1xxx
        assert ErrorCode::ParseError >= 1000
        assert ErrorCode::InvalidType < 2000

    invariant type_codes_are_2xxx
        assert ErrorCode::TypeMismatch >= 2000
        assert ErrorCode::ArgCountMismatch < 3000

    invariant link_codes_are_3xxx
        assert ErrorCode::LinkError >= 3000
        assert ErrorCode::SymbolNotExported < 4000
}

// SPDX-License-Identifier: Apache-2.0
// t27/specs/fpga/crossopt.t27
// T27 Cross-Module Optimization Specification
// Inter-module constant propagation, dead signal elimination, instance merging
// Uses flat arrays + count fields (parser-compatible)
// phi^2 + 1/phi^2 = 3 | TRINITY

module CrossOpt {

    pub struct CrossOptPass {
        name : &str,
        num_modules : u32,
        constants_propagated : u32,
        dead_signals_removed : u32,
        instances_merged : u32,
    }

    fn pass_zero() -> CrossOptPass {
        return CrossOptPass{
            .name = "empty",
            .num_modules = 0,
            .constants_propagated = 0,
            .dead_signals_removed = 0,
            .instances_merged = 0,
        };
    }

    fn pass_result(name: &str, mods: u32, consts: u32, dead: u32, merged: u32) -> CrossOptPass {
        return CrossOptPass{
            .name = name,
            .num_modules = mods,
            .constants_propagated = consts,
            .dead_signals_removed = dead,
            .instances_merged = merged,
        };
    }

    fn total_improvements(p: CrossOptPass) -> u32 {
        return p.constants_propagated + p.dead_signals_removed + p.instances_merged;
    }

    fn has_improvements(p: CrossOptPass) -> bool {
        return total_improvements(p) > 0;
    }

    fn improvement_density(p: CrossOptPass) -> u32 {
        if p.num_modules == 0 {
            return 0;
        }
        return total_improvements(p) / p.num_modules;
    }

    pub struct CrossOptReport {
        total_passes : u32,
        total_constants : u32,
        total_dead : u32,
        total_merged : u32,
        total_modules : u32,
    }

    fn report_ok(passes: u32, consts: u32, dead: u32, merged: u32, mods: u32) -> CrossOptReport {
        return CrossOptReport{
            .total_passes = passes,
            .total_constants = consts,
            .total_dead = dead,
            .total_merged = merged,
            .total_modules = mods,
        };
    }

    fn total_optimizations(r: CrossOptReport) -> u32 {
        return r.total_constants + r.total_dead + r.total_merged;
    }

    fn is_effective(r: CrossOptReport) -> bool {
        return total_optimizations(r) > 0;
    }

    // === Tests ===

    test pass_zero
        given p = pass_zero()
        then p.num_modules == 0
        and total_improvements(p) == 0
        and has_improvements(p) == false

    test pass_result_creation
        given p = pass_result("const_prop", 3, 10, 5, 2)
        then p.name == "const_prop"
        and p.num_modules == 3
        and total_improvements(p) == 17
        and has_improvements(p) == true

    test improvement_density
        given p = pass_result("opt", 5, 20, 10, 5)
        then improvement_density(p) == 7

    test improvement_density_zero
        given p = pass_zero()
        then improvement_density(p) == 0

    test report_creation
        given r = report_ok(3, 30, 15, 5, 10)
        then r.total_passes == 3
        and total_optimizations(r) == 50
        and is_effective(r) == true

    test report_empty
        given r = report_ok(0, 0, 0, 0, 0)
        then is_effective(r) == false

    invariant improvements_non_negative
        given p = pass_zero()
        assert total_improvements(p) >= 0

    bench improvement_density_latency
        measure: nanoseconds to improvement_density(pass_result("bench", 5, 20, 10, 5))
        target: < 50ns

    bench total_improvements_latency
        measure: nanoseconds to total_improvements(pass_result("bench", 10, 50, 25, 10))
        target: < 50ns
}

